44	// Set the (array of) exported name(s) of a (public) function to just
45	// contain the given string.
46	void SetExportedName(func::FuncOp f, StringRef name) {
47	  OpBuilder b(f);
48	  f->removeAttr(kTfSavedModelExportedNamesAttr);
49	  f->setAttr(kTfSavedModelExportedNamesAttr, b.getStrArrayAttr({name}));
50	}
51	
52	// Convert a savedmodel public function into a private function.
53	// This means we need to remove any attributes that are only allowed
54	// on exported (public) functions.
55	void Unexport(func::FuncOp f) {
56	  f.setVisibility(mlir::SymbolTable::Visibility::Private);
57	  f->removeAttr(kTfSavedModelExportedNamesAttr);
58	  for (int i = 0; i < f.getNumArguments(); ++i) {
59	    llvm::ArrayRef<mlir::NamedAttribute> attrs =
60	        mlir::function_interface_impl::getArgAttrs(f, i);
61	    for (NamedAttribute a : attrs) {
62	      if (a.getName().strref().starts_with("tf_saved_model.")) {
63	        f.removeArgAttr(i, a.getName());
64	      }
65	    }
66	  }
67	  for (int i = 0; i < f.getNumResults(); ++i) {
68	    for (NamedAttribute a : f.getResultAttrs(i)) {
69	      if (a.getName().strref().starts_with("tf_saved_model.")) {
70	        f.removeResultAttr(i, a.getName());
71	      }
72	    }
73	  }
74	}
