76	void AddFunctionsForExportedNamesPass::runOnOperation() {
77	  Block& module_body = getOperation().getRegion().front();
78	  for (auto f :
79	       llvm::make_early_inc_range(getOperation().getOps<func::FuncOp>())) {
80	    auto exported_names = GetExportedNames(f);
81	    if (exported_names.empty() || !f.isPublic()) continue;
82	
83	    if (exported_names.size() == 1 && exported_names[0] == f.getName()) {
84	      // Functions that already export themselves with their MLIR name
85	      // we can leave alone. This saves one level of indirection.
86	      return;
87	    }
88	
89	    f->removeAttr(kTfSavedModelExportedNamesAttr);  // so we don't clone it
90	
91	    // Rename to avoid name collisions with itself.
92	    f.setName(StringAttr::get(f->getContext(), f.getName() + "_internal"));
93	
94	    for (StringRef name : llvm::reverse(exported_names)) {
95	      // Create a "trampoline" function with the given name. So given
96	      //   func bar(...) {exported_names = ["foo"]}
97	      // we create
98	      //   func foo(...) {
99	      //     return bar(...)
100	      //   }
101	      func::FuncOp other = f.cloneWithoutRegions();
102	      other.setName(name);
103	      SetExportedName(other, name);
104	      module_body.push_front(other);
105	      other.addEntryBlock();
106	      OpBuilder builder(other.getRegion());
107	      auto call_op = mlir::func::CallOp::create(
108	          builder, f.getLoc(), f.getFunctionType().getResults(), f.getSymName(),
109	          other.getRegion().getArguments());
110	      mlir::func::ReturnOp::create(builder, f.getLoc(), call_op.getResults());
111	    }
112	
113	    Unexport(f);
114	  }
115	}
